pub fn list_position(mut n: Str, mut xs: Strings, mut i: i64) -> i64 {
    loop {
        if null_p(xs) {
            return -1i64;
        } else if string_eq_p(car(xs), n) {
            return i;
        } else {
            (xs, i) = (cdr(xs), i64_plus(i, 1i64));
            continue;
        }
    }
}

// The fixed widths but `i64`, a primitive of its own each: their names
// interned, their number past the list's.
pub fn fixed_base() -> i64 {
    1000i64
}

// `f32`'s operations (C220), numbered past the fixed widths'.
pub fn f32_base() -> i64 {
    3000i64
}

pub fn f32_names() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit("f32+"), kayak_rt::heap_cons(str_lit("f32-"), kayak_rt::heap_cons(str_lit("f32*"), kayak_rt::heap_cons(str_lit("f32/"), kayak_rt::heap_cons(str_lit("f32-min"), kayak_rt::heap_cons(str_lit("f32-max"), kayak_rt::heap_cons(str_lit("f32<"), kayak_rt::heap_cons(str_lit("f32<="), kayak_rt::heap_cons(str_lit("f32>"), kayak_rt::heap_cons(str_lit("f32>="), kayak_rt::heap_cons(str_lit("f32="), kayak_rt::heap_cons(str_lit("f32-abs"), kayak_rt::heap_cons(str_lit("f32-neg"), kayak_rt::heap_cons(str_lit("f32-sqrt"), kayak_rt::heap_cons(str_lit("f32-floor"), kayak_rt::heap_cons(str_lit("f32-ceiling"), kayak_rt::heap_cons(str_lit("f32-truncate"), kayak_rt::heap_cons(str_lit("f32-round"), kayak_rt::heap_cons(str_lit("f32-nan?"), kayak_rt::heap_cons(str_lit("f32-infinite?"), kayak_rt::heap_cons(str_lit("f32-finite?"), kayak_rt::heap_cons(str_lit("f32->string"), kayak_rt::heap_cons(str_lit("f32->int"), kayak_rt::heap_cons(str_lit("f32->f64"), kayak_rt::heap_cons(str_lit("int->f32"), kayak_rt::heap_cons(str_lit("f64->f32"), kayak_rt::heap_cons(str_lit("f32?"), kayak_rt::heap_cons(str_lit("f32->bits"), kayak_rt::heap_cons(str_lit("bits->f32"), kayak_rt::nil())))))))))))))))))))))))))))))
    })
}

pub fn prim_number(n: Str) -> i64 {
    let i = list_position(n, prim_list(), 0i64);
    if i64_gt_eq(i, 0i64) {
        i
    } else if string_member_p(n, f32_names()) {
        i64_plus(f32_base(), list_position(n, f32_names(), 0i64))
    } else if not(string_eq_p(fixed_type(n), str_lit(""))) {
        i64_plus(fixed_base(), intern_x(n))
    } else {
        failed_with_x(string_append(str_lit("the engine has no primitive "), n));
        0i64
    }
}

/// A literal's word, its object made in the heap if it is one.
pub fn literal_word_x(v: &'static Val) -> i64 {
    let tagcase_ = v;
    match *tagcase_ {
        Val::VInt(n) => {
            int_word_x(n)
        }
        Val::VReal(x) => {
            real_word_x(x)
        }
        Val::VChar(c) => {
            char_word(c)
        }
        Val::VString(s) => {
            string_word_x(s)
        }
        Val::VSymbol(s) => {
            symbol_word(intern_x(symbol_to_string(s)))
        }
        Val::VBool(b) => {
            bool_word(b)
        }
        Val::VUnit() => {
            w_unit()
        }
        Val::VNil() => {
            w_nil()
        }
        Val::VPrim(n, a) => {
            immediate(imm_prim(), prim_number(n))
        }
        Val::VCtor(t, n) => {
            let p = alloc_x(ob_ctor(), 2i64);
            obj_set_x(p, 0i64, fixnum(intern_x(t)));
            obj_set_x(p, 1i64, fixnum(n));
            p
        }
        Val::VTag(n) => {
            immediate(imm_tag(), n)
        }
        _ => {
            let other = tagcase_;
            failed_with_x(str_lit("the engine: a literal it cannot make"));
            0i64
        }
    }
}

// Quoted data, interned (C79): each pair and atom of a quote made once,
// at loading, a constant; an equal one found again by its text, so that
// equal quotes are one object, as FX-26's heap interns them.
pub enum Quoted {
    Quoted(Str, i64),
}

pub fn quoted(f0: Str, f1: i64) -> &'static Quoted {
    kayak_rt::heap_alloc(Quoted::Quoted(f0, f1))
}

pub fn quoteds() -> Ref<List<&'static Quoted>> {
    kayak_rt::kept_constant!(ONCE: Ref<List<&'static Quoted>>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<&'static Quoted>())
    })
}

pub fn found_quoted(mut key: Str, mut qs: List<&'static Quoted>) -> i64 {
    loop {
        if null_p(qs) {
            return -1i64;
        } else if {
            let tagcase_ = car(qs);
            match *tagcase_ {
                Quoted::Quoted(k, i) => {
                    string_eq_p(k, key)
                }
            }
        } {
            let tagcase_ = car(qs);
            match *tagcase_ {
                Quoted::Quoted(k, i) => {
                    return i;
                }
            }
        } else {
            qs = cdr(qs);
            continue;
        }
    }
}

/// A quoted datum's constant: its own, or an equal one's.
pub fn quoted_constant_x(d: &'static Sexp) -> i64 {
    let key = show_sexp(d);
    let found = found_quoted(key, get(quoteds()));
    if i64_gt_eq(found, 0i64) {
        found
    } else {
        let w = {
            let tagcase_ = d;
            match *tagcase_ {
                Sexp::Lst(ys, f, l, p) => {
                    if null_p(ys) {
                        w_nil()
                    } else if head_is_p(d, str_lit("#vector")) {
                        list_array_x(ob_vector(), constant_at(quoted_constant_x(lst(cdr(ys), f, l, p))))
                    } else if (sym_is_p(car(ys), str_lit(".")) && not(null_p(cdr(ys))) && null_p(cdr(cdr(ys)))) {
                        constant_at(quoted_constant_x(car(cdr(ys))))
                    } else {
                        let ca = quoted_constant_x(car(ys));
                        let cd = quoted_constant_x(lst(cdr(ys), f, l, p));
                        pair_x(constant_at(ca), constant_at(cd))
                    }
                }
                Sexp::Sym(n, f, p) => {
                    if string_eq_p(n, str_lit("#t")) {
                        bool_word(true)
                    } else if string_eq_p(n, str_lit("#f")) {
                        bool_word(false)
                    } else {
                        symbol_word(intern_x(n))
                    }
                }
                _ => {
                    let other = tagcase_;
                    let tagcase_ = lower(d, nil::<List<Str>>(), nil::<Str>());
                    match *tagcase_ {
                        Ir::ILit(v) => {
                            literal_word_x(v)
                        }
                        _ => {
                            let other2 = tagcase_;
                            w_unit()
                        }
                    }
                }
            }
        };
        let i = add_constant_x(w);
        set(quoteds(), kayak_rt::heap_cons(quoted(key, i), get(quoteds())));
        i
    }
}

pub fn kids_placed_x(mut ns: List<i64>) -> () {
    loop {
        if null_p(ns) {
            return ();
        } else {
            add_kid_x(car(ns));
            ns = cdr(ns);
            continue;
        }
    }
}

pub fn kids_of_x(ns: List<i64>) -> i64 {
    let at = get(kid_count());
    kids_placed_x(ns);
    at
}

/// A product's labels, interned, a range of `kids`: its start.
pub fn label_ids_x(ls: Strings) -> i64 {
    kids_of_x(label_numbers_x(ls))
}

pub fn label_numbers_x(ls: Strings) -> List<i64> {
    if null_p(ls) {
        nil::<i64>()
    } else {
        let n = intern_x(car(ls));
        kayak_rt::heap_cons(n, label_numbers_x(cdr(ls)))
    }
}

pub fn armxs_placed_x(mut xs: List<&'static Armx>) -> () {
    loop {
        if null_p(xs) {
            return ();
        } else {
            add_armx_x(car(xs));
            xs = cdr(xs);
            continue;
        }
    }
}

pub fn place_armxs_x(xs: List<&'static Armx>) -> i64 {
    let at = get(armx_count());
    armxs_placed_x(xs);
    at
}

/// `e`, numbered: its node's number, its children's before it.
pub fn number_x(e: &'static Ir) -> i64 {
    let tagcase_ = e;
    match *tagcase_ {
        Ir::ILit(v) => {
            add_node_x(n_lit({
                let tagcase_ = v;
                match *tagcase_ {
                    Val::VDatum(d) => {
                        quoted_constant_x(d)
                    }
                    _ => {
                        let other = tagcase_;
                        add_constant_x(literal_word_x(v))
                    }
                }
            }))
        }
        Ir::ILocal(d, s) => {
            add_node_x(n_local(d, s))
        }
        Ir::IGlobal(i, n) => {
            add_node_x(n_global(i))
        }
        Ir::ILambda(n, body, name, place) => {
            let start = get(node_count());
            let b = number_x(body);
            let l = add_node_x(n_lambda(n, b));
            owned_x(start, l, l);
            array_set_x(get(wheres()), i64_to_int(l), if string_eq_p(name, str_lit("")) {
                string_append(str_lit("a lambda ("), string_append(place, str_lit(")")))
            } else {
                string_append(name, string_append(str_lit(" ("), string_append(place, str_lit(")"))))
            });
            l
        }
        Ir::ICall(f, args) => {
            let at = number_all_x(kayak_rt::heap_cons(f, args));
            add_node_x(n_call(at, i64_plus(size(args), 1i64)))
        }
        Ir::IIf(x, y, z) => {
            let a = number_x(x);
            let b = number_x(y);
            let c = number_x(z);
            add_node_x(n_if(a, b, c))
        }
        Ir::ISeq(es) => {
            let at = number_all_x(es);
            add_node_x(n_seq(at, size(es)))
        }
        Ir::ILet(es, body) => {
            let at = number_all_x(es);
            let b = number_x(body);
            add_node_x(n_let(at, size(es), b))
        }
        Ir::ILetrec(es, body) => {
            let at = number_all_x(es);
            let b = number_x(body);
            add_node_x(n_letrec(at, size(es), b))
        }
        Ir::IDefine(i, x) => {
            let a = number_x(x);
            add_node_x(n_define(i, a))
        }
        Ir::ISum(t, x) => {
            let a = number_x(x);
            add_node_x(n_sum(intern_x(t), a))
        }
        Ir::IProduct(ls, es) => {
            let labels = label_ids_x(ls);
            let at = number_all_x(es);
            add_node_x(n_product(labels, at, size(es)))
        }
        Ir::IExtract(l, x) => {
            let a = number_x(x);
            add_node_x(n_extract(intern_x(l), a))
        }
        Ir::ITagcase(x, arms, default) => {
            let a = number_x(x);
            let start = arms_numbered_x(arms);
            let d = number_x(default);
            add_node_x(n_tagcase(a, start, size(arms), d))
        }
        Ir::IPrompt(t, h, body) => {
            let a = number_x(t);
            let b = number_x(h);
            let c = number_x(body);
            add_node_x(n_prompt(a, b, c))
        }
    }
}

/// Each of `es` numbered, then their numbers a range of `kids`: its start.
pub fn number_all_x(es: List<&'static Ir>) -> i64 {
    kids_of_x(numbers_x(es))
}

pub fn numbers_x(es: List<&'static Ir>) -> List<i64> {
    if null_p(es) {
        nil::<i64>()
    } else {
        let n = number_x(car(es));
        kayak_rt::heap_cons(n, numbers_x(cdr(es)))
    }
}

pub fn arms_numbered_x(arms: List<&'static Arm>) -> i64 {
    let made = arm_entries_x(arms);
    place_armxs_x(made)
}

pub fn arm_entries_x(arms: List<&'static Arm>) -> List<&'static Armx> {
    if null_p(arms) {
        nil::<&'static Armx>()
    } else {
        let tagcase_ = car(arms);
        match *tagcase_ {
            Arm::Arm(t, n, body) => {
                let b = number_x(body);
                kayak_rt::heap_cons(armx(intern_x(t), n, b), arm_entries_x(cdr(arms)))
            }
        }
    }
}

